 default{$schemeName='Black Red';$bg='#000000';$fg='#F7F7F7';$blue='#FF2D2D';$brightBlue='#FF5555';$cursor='#FF7070';$select='#381010';$tab='#B51616';$g1=@(0,0,0);$g2=@(12,2,2);$accent=@(255,45,45);$accentBright=@(255,85,85);$consoleAccent='Red';$consoleDark='DarkRed'}
