if(-not(Test-Path 'C:\Program Files\PowerShell\7\pwsh.exe')){$wg=Get-Command winget.exe -ErrorAction SilentlyContinue;if($wg){& $wg.Source install --id Microsoft.PowerShell --source winget --silent --accept-package-agreements --accept-source-agreements|Out-Null}}
$map=@{Bold='';Clean='';'Ultra Fast'=''}
