$profileText=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($map[$Mode]))
if($Theme -in @('Black Red','Black Green','Pure Black')){
 $profileText=$profileText.Replace('BLUE FAST MODE',(($schemeName.ToUpperInvariant())+' MODE'))
