foreach($p in $profiles){New-Item -ItemType Directory -Force -Path (Split-Path -Parent $p)|Out-Null;Backup-Once $p;[IO.File]::WriteAllText($p,$profileText,(New-Object Text.UTF8Encoding($false)))}
$local=[Environment]::GetFolderPath('LocalApplicationData')
