 New-Item -ItemType Directory -Force -Path $bgDir|Out-Null
 $bmp=New-Object Drawing.Bitmap 1920,1080;$gfx=[Drawing.Graphics]::FromImage($bmp);$gfx.SmoothingMode=[Drawing.Drawing2D.SmoothingMode]::AntiAlias
 $rect=New-Object Drawing.Rectangle 0,0,1920,1080
 $grad=New-Object Drawing.Drawing2D.LinearGradientBrush $rect,([Drawing.Color]::FromArgb($g1[0],$g1[1],$g1[2])),([Drawing.Color]::FromArgb($g2[0],$g2[1],$g2[2])),25
 $gfx.FillRectangle($grad,$rect)
 $grid=New-Object Drawing.Pen ([Drawing.Color]::FromArgb(18,$accent[0],$accent[1],$accent[2])),1
 for($x=0;$x -lt 1920;$x+=80){$gfx.DrawLine($grid,$x,0,$x,1080)};for($y=0;$y -lt 1080;$y+=80){$gfx.DrawLine($grid,0,$y,1920,$y)}
 $neon=New-Object Drawing.Pen ([Drawing.Color]::FromArgb(68,$accent[0],$accent[1],$accent[2])),6
 $pts=@((New-Object Drawing.Point 80,920),(New-Object Drawing.Point 420,680),(New-Object Drawing.Point 760,760),(New-Object Drawing.Point 1110,430),(New-Object Drawing.Point 1510,540),(New-Object Drawing.Point 1860,190))
 $gfx.DrawLines($neon,$pts);$bmp.Save($bgPath,[Drawing.Imaging.ImageFormat]::Png)
 $neon.Dispose();$grid.Dispose();$grad.Dispose();$gfx.Dispose();$bmp.Dispose()
}
$paths=@((Join-Path $local 'Packages\Microsoft.WindowsTerminal_8wekyb3d8bbwe\LocalState\settings.json'),(Join-Path $local 'Packages\Microsoft.WindowsTerminalPreview_8wekyb3d8bbwe\LocalState\settings.json'),(Join-Path $local 'Microsoft\Windows Terminal\settings.json'))
