 Set-Prop $j 'defaultProfile' '{574e775e-4f2a-5b96-ac1e-a2962a402336}';Set-Prop $j 'alwaysShowTabs' $true;Set-Prop $j 'showTabsInTitlebar' $true;Set-Prop $j 'useAcrylicInTabRow' $Acrylic;Set-Prop $j 'theme' 'dark';$actions=@([pscustomobject]@{command=[pscustomobject]@{action='splitPane';split='right';splitMode='duplicate'};keys='alt+shift+d'},[pscustomobject]@{command=[pscustomobject]@{action='splitPane';split='down';splitMode='duplicate'};keys='alt+shift+s'},[pscustomobject]@{command='closePane';keys='alt+shift+w'});Set-Prop $j 'actions' $actions
 if(-not $j.profiles){Set-Prop $j 'profiles' ([pscustomobject]@{})};if(-not $j.profiles.defaults){Set-Prop $j.profiles 'defaults' ([pscustomobject]@{})};$d=$j.profiles.defaults
