 foreach($kv in @{antialiasingMode='cleartype';colorScheme=$schemeName;cursorShape=$cursorShape;cursorHeight=25;opacity=96;padding=$pad;scrollbarState='hidden';useAcrylic=$Acrylic;intenseTextStyle='bright'}.GetEnumerator()){Set-Prop $d $kv.Key $kv.Value}
 if($Mode -eq 'Bold'){Set-Prop $d 'backgroundImage' $bgPath;Set-Prop $d 'backgroundImageOpacity' $BgOpacity;Set-Prop $d 'backgroundImageStretchMode' 'uniformToFill';Set-Prop $d 'backgroundImageAlignment' 'center'}else{foreach($n in @('backgroundImage','backgroundImageOpacity','backgroundImageStretchMode','backgroundImageAlignment')){if($d.PSObject.Properties[$n]){$d.PSObject.Properties.Remove($n)}}}
 if(-not $d.font){Set-Prop $d 'font' ([pscustomobject]@{})};Set-Prop $d.font 'face' 'Cascadia Mono';Set-Prop $d.font 'size' $FontSize;Set-Prop $d.font 'weight' 'normal'
 $j.schemes=@(@($j.schemes|Where-Object{$_.name -notin @('Purple Neon','Cyan Slate','Electric Blue','Midnight Blue','Ice Blue','Black Glass Green','Black Glass Red','Black Glass Cyan','Black Glass Amber','Black Red','Black Green','Pure Black')})+$scheme)
 foreach($pr in @($j.profiles.list)){if($pr.guid -eq '{574e775e-4f2a-5b96-ac1e-a2962a402336}' -or $pr.source -eq 'Windows.Terminal.PowershellCore'){Set-Prop $pr 'name' 'PowerShell 7';Set-Prop $pr 'tabColor' $tab}elseif($pr.guid -eq '{61c54bbd-c2c6-5271-96e7-009a87ff44bf}'){Set-Prop $pr 'name' 'Windows PowerShell';Set-Prop $pr 'tabColor' '#0F172A'}}
